import { paths } from '~/paths'
import { ItemLink } from '~/ui/parts/ItemLink'

import main01 from './main01.jpg'

import { name } from './name'

/** @jsxImportSource @emotion/react */
//import { css } from '@emotion/react'


export default function Link() {
  // Videoのループ再生時の例外問題で動画がちらつくことがあるため、写真を裏に表示しておくことでちらつき防止とする。（本来写真は不要）
  return (
    <ItemLink path={paths.block.path()} id={name.id} thumbnailImage={main01}>
      {name.title}
    </ItemLink>
  )
}


